tool.command:

  ln -f -s ${input_actpass1_path} ${input_actpass1_path}_`echo $$`.${input_actpass1_path.ext};

  ln -f -s ${input_actpass2_path} ${input_actpass2_path}_`echo $$`.${input_actpass2_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

haddock3_actpass_to_ambig

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__pass_to_act__dq__:${properties.pass_to_act},__dq__segid_one__dq__:__dq__${properties.segid_one}__dq__,__dq__segid_two__dq__:__dq__${properties.segid_two}__dq__,__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_actpass1_path) != 'None':
    --input_actpass1_path ${input_actpass1_path}_`echo $$`.${input_actpass1_path.ext}
  #end if

  #if str($input_actpass2_path) != 'None':
    --input_actpass2_path ${input_actpass2_path}_`echo $$`.${input_actpass2_path.ext}
  #end if


  --output_tbl_path $outname_output_tbl_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_actpass1_path}_`echo $$`.${input_actpass1_path.ext};

  rm -f ${input_actpass2_path}_`echo $$`.${input_actpass2_path.ext};


  if test -f $outname_output_tbl_path; then mv $outname_output_tbl_path $output_tbl_path; fi;
